	@Test
	void groupedCountOnEmptyInputHasNoGroupRows() {
		String query = "SELECT ?s (COUNT(*) AS ?count) WHERE { ?s <" + P + "> ?o } GROUP BY ?s";
		try (Repositories repositories = openRepositories()) {
			assertResultBag(repositories, query, bag());

			TupleExpr optimized = optimizedPlan(repositories.lmdb(), query);
			Group group = keylessGroup(optimized, false);
			assertNotNull(group, "The grouped aggregate must remain visible in the natural public plan: " + optimized);
			assertEquals(List.of("s"), List.copyOf(group.getGroupBindingNames()), optimized::toString);
			// This statement pattern has no exact empty-range receipt, so its planned estimate is not a proof of zero.
		}
	}

	@Test
	void havingFalseAndLimitZeroDoNotChangeTheInnerGlobalGroupCardinality() {
		List<String> queries = List.of(
				"SELECT (COUNT(*) AS ?count) WHERE { ?s <" + P + "> ?o } HAVING(false)",
				"SELECT (COUNT(*) AS ?count) WHERE { ?s <" + P + "> ?o } LIMIT 0");
		try (Repositories repositories = openRepositories()) {
			for (String query : queries) {
				assertResultBag(repositories, query, bag());
				TupleExpr optimized = optimizedPlan(repositories.lmdb(), query);
				List<Group> globalGroups = groups(optimized).stream()
						.filter(group -> group.getGroupBindingNames().isEmpty())
						.toList();
				assertTrue(globalGroups.size() <= 1,
						"The optimized plan may retain or eliminate the global Group, but must not duplicate it: "
								+ optimized);
				if (!globalGroups.isEmpty()) {
					assertEquals(1.0d,
							globalGroups.getFirst()
									.getDoubleMetricPlanned(TelemetryMetricNames.PLANNED_CARDINALITY_ROWS),
							0.0d,
							"A retained keyless Group produces one row before HAVING or LIMIT changes the enclosing result: "
									+ optimized);
				}
			}
		}
	}

